        detected: false,
        whitelist: new Set(),
        cardPriority: [],
        savedCardsReady: false,
        savedCardsError: '',
        offersByAccount: new Map(),
        scanReports: new Map(),
        offerScanTimes: new Map(),
        pendingEnrollments: new Set(),
        savedOffersError: '',
        busy: null,
        cancelRequested: false,
        requestInFlight: false,
        nextRequestAt: 0,
        cooldownUntil: 0,
        discoveryRetryAt: 0,
        filter: '',
